-- Integration assertions. All synthetic users, sessions, groups and meetings are rolled back.
-- No network calls, actual audio, OpenAI calls or changes to existing users.
begin;
do $$
declare manager uuid:=gen_random_uuid(); master uuid:=gen_random_uuid(); social uuid:=gen_random_uuid();
 sm uuid:=gen_random_uuid(); sa uuid:=gen_random_uuid(); ss uuid:=gen_random_uuid();
 device uuid:=gen_random_uuid(); other_device uuid:=gen_random_uuid(); client uuid:=gen_random_uuid(); other_client uuid:=gen_random_uuid();
 cue uuid:=gen_random_uuid(); meeting uuid:=gen_random_uuid(); token text:=repeat('a',64); value jsonb; before_count integer; task_one uuid;
begin
 assert not has_table_privilege('anon','public.client_meetings','select');
 assert not has_table_privilege('authenticated','public.meeting_utterances','select');
 assert not has_function_privilege('anon','public.meeting_command_v2(text,jsonb,uuid,uuid,text)','execute');
 assert not has_table_privilege('authenticated','public.meeting_device_sessions','select');
 assert not has_function_privilege('authenticated','public.meeting_actor(uuid,uuid,text)','execute');
 assert not has_function_privilege('anon','public.meeting_command_v2(text,jsonb,uuid,uuid,text)','execute');
 assert not has_function_privilege('authenticated','public.claim_meeting_chunks()','execute');
 insert into auth.users(id) values(manager),(master),(social);
 insert into public.profiles(user_id,full_name,role,is_master) values(manager,'__MEET_TEST_MANAGER__','gestor',false),(master,'__MEET_TEST_MASTER__','admin',true),(social,'__MEET_TEST_SOCIAL__','social_media',false);
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sm,manager,now(),now()),(sa,master,now(),now()),(ss,social,now(),now());
 insert into public.whatsapp_grupos(id,group_id,nome,manager_user_id) values(client,'__meeting_test_'||client,'__MEET_TEST_CLIENT__',manager),(other_client,'__meeting_test_'||other_client,'__MEET_TEST_OTHER__',master);
 begin perform public.meeting_actor(social,ss);raise exception 'TEST: social media allowed';exception when insufficient_privilege then null;end;
 begin perform public.meeting_actor(manager,sa);raise exception 'TEST: wrong auth session allowed';exception when insufficient_privilege then null;end;
 value:=public.meeting_command_v2('pair',jsonb_build_object('deviceId',device,'challenge',token,'label','Test computer'),manager,sm);
 assert value->>'status'='pending';
 begin perform public.meeting_actor(null,null,token);raise exception 'TEST: unapproved device allowed';exception when insufficient_privilege then null;end;
 begin perform public.meeting_command_v2('device_update',jsonb_build_object('deviceId',device,'status','approved'),manager,sm);raise exception 'TEST: manager approved device';exception when insufficient_privilege then null;end;
 perform public.meeting_command_v2('device_update',jsonb_build_object('deviceId',device,'status','approved'),master,sa);
 assert (public.meeting_actor(null,null,token)->>'userId')::uuid=manager;
 value:=public.meeting_command_v2('bootstrap','{}',null,null,token);
 assert jsonb_array_length(value->'clients')=1;
 assert value->'clients'->0->>'id'=client::text;
 begin perform public.meeting_command_v2('start',jsonb_build_object('requestId',meeting,'clientId',other_client,'meetCode','abc-defg-hij','title','Test','consent',true),null,null,token);raise exception 'TEST: wrong client allowed';exception when insufficient_privilege then null;end;
 value:=public.meeting_command_v2('start',jsonb_build_object('requestId',meeting,'clientId',client,'meetCode','abc-defg-hij','title','Test','consent',true),null,null,token);
 assert value->>'id'=meeting::text;
 value:=public.meeting_command_v2('start',jsonb_build_object('requestId',meeting,'clientId',client,'meetCode','abc-defg-hij','title','Test','consent',true),null,null,token);
 assert value->>'id'=meeting::text;
 begin perform public.meeting_command_v2('start',jsonb_build_object('requestId',gen_random_uuid(),'clientId',client,'meetCode','abc-defg-hik','title','Test','consent',true),null,null,token);raise exception 'TEST: second recorder allowed';exception when serialization_failure then null;end;
 perform public.meeting_command_v2('captions',jsonb_build_object('meetingId',meeting,'items',jsonb_build_array(jsonb_build_object('id',cue,'speaker','Participante teste','text','Olá','startMs',0,'endMs',1000,'revision',1))),null,null,token);
 perform public.meeting_command_v2('captions',jsonb_build_object('meetingId',meeting,'items',jsonb_build_array(jsonb_build_object('id',cue,'speaker','Participante teste','text','Olá, equipe','startMs',0,'endMs',2000,'revision',2))),null,null,token);
 perform public.meeting_command_v2('captions',jsonb_build_object('meetingId',meeting,'items',jsonb_build_array(jsonb_build_object('id',cue,'speaker','Participante teste','text','Olá','startMs',0,'endMs',1000,'revision',1))),null,null,token);
 assert (select count(*) from public.meeting_utterances where meeting_id=meeting)=1;
 assert (select text from public.meeting_utterances where meeting_id=meeting)='Olá, equipe';
 begin perform public.meeting_command_v2('captions',jsonb_build_object('meetingId',meeting,'items',jsonb_build_array(jsonb_build_object('id',cue,'speaker','Outra pessoa','text','Não atribuir','startMs',0,'endMs',2000,'revision',3))),null,null,token);raise exception 'TEST: replaced speaker';exception when raise_exception then if sqlerrm<>'caption_conflict' then raise;end if;end;
 begin perform public.meeting_command_v2('trash',jsonb_build_object('meetingId',meeting,'version',1,'confirmed',true),manager,sm);raise exception 'TEST: trashed active meeting';exception when raise_exception then if sqlerrm<>'meeting_busy' then raise;end if;end;
 begin perform public.meeting_command_v2('edit',jsonb_build_object('meetingId',meeting,'version',1,'title','Device edit'),null,null,token);raise exception 'TEST: extension edit permitted';exception when insufficient_privilege then null;end;
 value:=public.meeting_command_v2('reserve_chunk',jsonb_build_object('meetingId',meeting,'seq',0,'durationMs',60000,'offsetMs',0,'contentHash',repeat('b',64),'sizeBytes',100),null,null,token);
 assert value->>'uploaded'='false';
 perform public.meeting_command_v2('commit_chunk',jsonb_build_object('meetingId',meeting,'seq',0,'contentHash',repeat('b',64)),null,null,token);
 value:=public.meeting_command_v2('reserve_chunk',jsonb_build_object('meetingId',meeting,'seq',0,'durationMs',60000,'offsetMs',0,'contentHash',repeat('b',64),'sizeBytes',100),null,null,token);
 assert value->>'uploaded'='true';
 begin perform public.meeting_command_v2('reserve_chunk',jsonb_build_object('meetingId',meeting,'seq',0,'durationMs',60000,'offsetMs',0,'contentHash',repeat('c',64),'sizeBytes',100),null,null,token);raise exception 'TEST: duplicate chunk replaced';exception when raise_exception then if sqlerrm<>'chunk_conflict' then raise;end if;end;
 assert (select count(*) from public.meeting_chunks where meeting_id=meeting)=1;
 perform public.meeting_command_v2('stop',jsonb_build_object('meetingId',meeting,'expectedChunks',1),null,null,token);
 assert (select status from public.client_meetings where id=meeting)='finalizing';
 -- Simulate provider output only; no provider requests.
 update public.meeting_chunks set status='done',transcript='Teste controlado' where meeting_id=meeting;
 update public.client_meetings set status='ready',summary='{"summary":"Teste","actions":["Confirmar orçamento"],"decisions":[],"goals":[],"openQuestions":[]}' where id=meeting;
 begin perform public.meeting_command_v2('review',jsonb_build_object('meetingId',meeting,'notes','Test'),manager,sm);raise exception 'TEST: missing version accepted';exception when serialization_failure then null;end;
 perform public.meeting_command_v2('review',jsonb_build_object('meetingId',meeting,'notes','Test','version',1),manager,sm);
 begin perform public.meeting_command_v2('review',jsonb_build_object('meetingId',meeting,'notes','Test','version',1),manager,sm);raise exception 'TEST: stale edit accepted';exception when serialization_failure then null;end;
 value:=public.meeting_command_v2('create_task',jsonb_build_object('meetingId',meeting,'index',0,'title','Tarefa teste'),manager,sm);task_one:=(value->>'taskId')::uuid;
 value:=public.meeting_command_v2('create_task',jsonb_build_object('meetingId',meeting,'index',0,'title','Tarefa teste'),manager,sm);assert (value->>'taskId')::uuid=task_one;
 perform public.meeting_command_v2('edit',jsonb_build_object('meetingId',meeting,'title','Título atualizado','description','Pauta revisada','version',2),manager,sm);
 assert (select version from public.client_meetings where id=meeting)=3;
 begin perform public.meeting_command_v2('edit',jsonb_build_object('meetingId',meeting,'title','Desatualizado','version',2),manager,sm);raise exception 'TEST: stale title overwrite';exception when serialization_failure then null;end;
 perform public.meeting_command_v2('trash',jsonb_build_object('meetingId',meeting,'version',3,'confirmed',true),manager,sm);
 value:=public.meeting_command_v2('bootstrap',jsonb_build_object('clientId',client),manager,sm);
 assert jsonb_array_length(value->'meetings')=0;
 value:=public.meeting_command_v2('bootstrap',jsonb_build_object('clientId',client,'trash',true),manager,sm);
 assert jsonb_array_length(value->'meetings')=1;
 begin perform public.meeting_command_v2('review',jsonb_build_object('meetingId',meeting,'notes','blocked','version',4),manager,sm);raise exception 'TEST: edited trash';exception when raise_exception then if sqlerrm<>'meeting_deleted' then raise;end if;end;
 perform public.meeting_command_v2('restore',jsonb_build_object('meetingId',meeting,'version',4,'confirmed',true),manager,sm);
 assert (select deleted_at from public.client_meetings where id=meeting) is null;
 assert (select count(*) from public.meeting_tasks where meeting_id=meeting)=1;
 update public.whatsapp_grupos set manager_user_id=master where id=client;
 begin perform public.meeting_command_v2('detail',jsonb_build_object('meetingId',meeting),manager,sm);raise exception 'TEST: former manager retained access';exception when insufficient_privilege then null;end;
 perform public.meeting_command_v2('device_update',jsonb_build_object('deviceId',device,'status','revoked'),master,sa);
 begin perform public.meeting_actor(null,null,token);raise exception 'TEST: revoked token allowed';exception when insufficient_privilege then null;end;
 delete from auth.sessions where id=sm;
 begin perform public.meeting_actor(manager,sm);raise exception 'TEST: logged out session allowed';exception when insufficient_privilege then null;end;
end $$;
rollback;
select 'PASS v2: original authorization plus caption revisions, immutable attribution, trash/restore, optimistic edits, device write isolation, task preservation; fixtures rolled back' as verification;
